using System; using Server; using Server.Commands; namespace Server.Misc { public class ForceDungeonTickCommand { public static void Initialize() { CommandSystem.Register("ForceDungeonTick", AccessLevel.GameMaster, new CommandEventHandler(ForceDungeonTick_OnCommand)); } [Usage("ForceDungeonTick")] [Description("Forces the Trammel and Felucca dungeon respawn tick.")] private static void ForceDungeonTick_OnCommand(CommandEventArgs e) { e.Mobile.SendMessage("Forcing Dungeon Spawns..."); DungeonManager.ProcessFacetDungeons(Map.Trammel); DungeonManager.ProcessFacetDungeons(Map.Felucca); e.Mobile.SendMessage("Dungeon Spawns Forced!"); } } }
